def p_exactly(k):
    return (C(PICK, k) * C(N - PICK, PICK - k)) / C(N, PICK)

def p_single_atleast(k):
    return sum(p_exactly(j) for j in range(k, PICK + 1))

def p_any_atleast(k, T):
    return 1 - (1 - p_single_atleast(k)) ** T

def probability_profile(T):
    return {
        "T": T,
        "ge2": p_any_atleast(2, T), "ge3": p_any_atleast(3, T),
        "ge4": p_any_atleast(4, T), "eq5": 1 - (1 - p_exactly(5)) ** T,
    }

def backtest(s, draws=None):
    draws = draws if draws is not None else load_draws()
    sets = [set(t) for t in s]
    bucket = [0] * 6
    for d in draws:
        ds = set(d); mx = 0
        for t in sets:
            m = len(t & ds)
            if m > mx: mx = m
            if m == PICK: break
        bucket[mx] += 1
    total = len(draws)
    ge2 = sum(bucket[2:]); ge3 = sum(bucket[3:]); ge4 = sum(bucket[4:])
    return {"total": total, "ge2": ge2, "ge3": ge3, "ge4": ge4, "eq5": bucket[5],
            "rate2": ge2 / total, "rate3": ge3 / total, "rate4": ge4 / total, "rate5": bucket[5] / total}

