def build_messages(payload):
    ctx = payload.get("context") or {}
    app = payload.get("app")
    sys_msg = {"universal": UNIVERSAL_SYSTEM_PROMPT, "supersete": SUPERSETE_SYSTEM_PROMPT,
               "scratch": SCRATCH_SYSTEM_PROMPT}.get(app, SYSTEM_PROMPT)
    if ctx:
        sys_msg += "\n\nCURRENT APP STATE:\n" + json.dumps(ctx, indent=2)
    msgs = [{"role": "system", "content": sys_msg}]
    for m in payload.get("messages", []):
        if m.get("role") in ("user", "assistant") and m.get("content"):
            msgs.append({"role": m["role"], "content": m["content"]})
    return msgs

@mcp.tool()
def brutal_ledger(tickets: list[list[int]], jackpot: float = 125000, match4: float = 255,
                  match3: float = 10, match2: float = 0, cost: float = 1.0) -> str:
    prizes = {2: match2, 3: match3, 4: match4, 5: jackpot}
    draws = E.load_draws()
    lr = E.ledger_run(tickets, draws, prizes=prizes, jackpot=jackpot, cost=cost)
    ctrl = E.montecarlo_control(len(tickets), draws, prizes=prizes, jackpot=jackpot, cost=cost, runs=150)
    pct = E.percentile_of(lr["net"], ctrl)
    lr["control"] = {"median": round(ctrl[len(ctrl) // 2], 2), "percentile": pct}
    lr["beat_random"] = pct is not None and pct > 0.5
    lr.pop("equity", None)  # too long for chat
    return json.dumps(lr)
